n \n symbol #generalize : Π [a], π a → Tactic;\n builtin \"generalize\" ≔ #generalize;\n \n symbol #have : String → Π [a], π a → Tactic;\n builtin \"have\" ≔ #have; \n \n symbol #induction : Tactic;\n builtin \"induction\" ≔ #induction; \n \n symbol #remove : Π [a], π a → Tactic;\n builtin \"remove\" ≔ #remove;\n \n symbol #reflexivity : Tactic;\n builtin \"reflexivity\" ≔ #reflexivity;\n \n symbol #set : String → Π [a], π a → Tactic;\n builtin \"set\" ≔ #set;\n \n symbol #simplify : Tactic;\n builtin \"simplify\" ≔ #simplify;\n\n symbol #simplify_beta : Tactic;\n builtin \"simplify rule off\" ≔ #simplify_beta;\n \n symbol #solve : Tactic;\n builtin \"solve\" ≔ #solve;\n \n symbol #symmetry : Tactic;\n builtin \"symmetry\" ≔ #symmetry;\n \n symbol #try : Tactic;\n builtin \"try\" ≔ #try;\n \n symbol #why3 : Tactic;\n builtin \"why3\" ≔ #why3; \n\n \n // necessary in order to define the tactics\n protected symbol set0 : Set;\n rule τ set0 ↪ Set;\n \n \n/******************************************************************************\n*  Definition of Leo-III simplification tactic        \n******************************************************************************/\n \n symbol applyAny : \uD835\uDD43 tactic → Tactic;\n rule applyAny ($t0 ⸬ $tl) ↪ $t0 #orelse (applyAny $tl)\n with applyAny □ ↪ #fail;\n \n symbol listOfAllSimpRules ≔ ((#rewrite \"\" \"\" ∨_idem) ⸬ (#rewrite \"\" \"\" em_eq_l) ⸬ (#rewrite \"\" \"\" em_eq_r) ⸬ (#rewrite \"\" \"\" ∨⊤) ⸬ \n     (#rewrite \"\" \"\" ⊤∨) ⸬ (#rewrite \"\" \"\" ∨⊥) ⸬ (#rewrite \"\" \"\" ⊥∨) ⸬ (#rewrite \"\" \"\" ∧_idem) ⸬ (#rewrite \"\" \"\" ∧_contra_r) ⸬ (#rewrite \"\" \"\" ∧_contra_l) ⸬ \n     (#rewrite \"\" \"\" ∧⊤) ⸬ (#rewrite \"\" \"\" ⊤∧) ⸬ (#rewrite \"\" \"\" ∧⊥) ⸬ (#rewrite \"\" \"\" ⊥∧) ⸬ (#rewrite \"\" \"\" ⇒⊤) ⸬ (#rewrite \"\" \"\" ⊥⇒) ⸬ (#rewrite \"\" \"\" ⊤⇒) ⸬ \n     (#rewrite \"\" \"\" ⇒⊥) ⸬ (#rewrite \"\" \"\" ⇒_idem) ⸬ (#rewrite \"\" \"\" ⇔⊤) ⸬ (#rewrite \"\" \"\" ⊤⇔) ⸬ (#rewrite \"\" \"\" ⊥⇔) ⸬ (#rewrite \"\" \"\" ⇔⊥) ⸬ \n     (#rewrite \"\" \"\" ⇔_idem) ⸬ (#rewrite \"\" \"\" ¬⊤) ⸬ (#rewrite \"\" \"\" ¬⊥) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" =⊤) ⸬ (#rewrite \"\" \"\" ⊤=) ⸬ \n     (#rewrite \"\" \"\" =⊥) ⸬ (#rewrite \"\" \"\" ⊥=) ⸬ (#rewrite \"\" \"\" =_idem) ⸬ (#rewrite \"\" \"\" ¬=⊥) ⸬ (#rewrite \"\" \"\" ¬⊥=) ⸬ (#rewrite \"\" \"\" ¬=⊤) ⸬ \n     (#rewrite \"\" \"\" ¬⊤=) ⸬ (#rewrite \"\" \"\" ¬=_idem) ⸬ (#rewrite \"\" \"\" ∀_const) ⸬ (#rewrite \"\" \"\" ∃_const) ⸬ (#rewrite \"\" \"\" polarity_switch) ⸬ (#refine \"⊤ᵢ\") ⸬ □);\n \n symbol applyAllSimplifications ≔ #repeat (applyAny listOfAllSimpRules);\n\n\n/******************************************************************************\n*  Definition of additional rules for clausification      \n******************************************************************************/\n\nopaque symbol ¬∀=∃¬ (t : Set) (p : τ (t ⤳ o)) : //lemma6\nπ (¬(∀ p) = (`∃ (x : τ t), ¬ (p x)))≔\nbegin\nassume t p;\nrefine propExt (¬ (∀ p)) (`∃ x, ¬ (p x)) _ _\n{assume h;\n    refine ∨ₑ (em (`∃ x, ¬ p x)) _ _\n    {assume he; refine he}\n    {assume hne;\n        have forall_p : Π x : τ t, π (p x)\n            {assume a; refine ¬¬ₑ (p a) (λ hp, hne (∃ᵢ [t] [λ y, ¬ p y] a hp))};\n        refine ⊥ₑ (h (λ a, forall_p a))}}\n{assume h h2;\n    refine ∃ₑ [t] [λ y, ¬ p y] h (λ a hna, hna (h2 a))}\nend;\n\nopaque symbol ¬∃=∀¬ (t : Set) (p : τ (t ⤳ o)) : // lemma7\nπ (¬(∃ p) = (`∀ (x : τ t), ¬ p x))≔     \nbegin\nassume t p;\nrefine propExt (¬ (∃ p)) (`∀ x, ¬ p x) _ _\n{assume h a ha; refine h (∃ᵢ [t] [p] a ha)}\n{assume h1 h2; refine ∃ₑ [t] [p] h2 (λ a ha, (h1 a) ha)}\nend;\n\n\n//  Skolemisazion\n\n\nopaque symbol εᵢ_rev :  Π [a: Set], Π p: (τ a → Prop),  π (p (ε p)) → π (∃ p)≔\nbegin\nassume a p h;\nrefine ∃ᵢ [a] [p] (ε p) h\nend;\n\nopaque symbol ∃_skolem (a: Set) (p: τ (a ⤳ o)) :  \n π ((∃ p) = (p (ε p)))≔\nbegin\n assume a p;\n refine propExt (∃ p) (p (ε p)) (εᵢ [a] p) (εᵢ_rev [a] p)\nend;\n\nopaque symbol ∀_skolem (a: Set) (p: τ (a ⤳ o)) :  \nπ (¬ (∀ p) = ¬ (p (ε (λ x, ¬ (p x)))))≔\nbegin\nassume a p;\nrewrite ¬∀=∃¬;\nrefine  propExt (`∃ x, ¬ (p x)) (¬ (p (ε (λ x, ¬ (p x))))) _ _\n    {assume h; refine ind_eq (eq_sym (∃_skolem a (λ x, ¬ (p x)))) (λ x, x) h}\n    {assume h; refine ind_eq (∃_skolem a (λ x, ¬ (p x))) (λ x, x) h}\nend;\n\n\n//Quantifier Distributivity\n\nopaque symbol ∀∧_dist_r t a (p : τ(t ⤳ o)): π ((a ∧ ∀ p) = (`∀ x, a ∧ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∧ ∀ p) (∀(λ x, a ∧ p x)) _ _\n        {assume h x;\n        refine ∧ᵢ (∧ₑ₁ h) ((∧ₑ₂ h) x)}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∧ᵢ (∧ₑ₁ (h (el t))) h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            have H1: π (p (ε (λ x, ¬ (p x))))\n                {refine ∧ₑ₂ (h (ε (λ x, ¬ (p x))))};\n            refine ⊥ₑ (H0 H1)}}\nend;\n\nopaque symbol ∀∧_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∧ a) = (`∀ x,p x ∧ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∧ a) (`∀ x, p x ∧ a) _ _\n        {assume h0 x;\n        rewrite ∧_com;\n        refine (=⇒ ((∀∧_dist_r t a p)) (=⇒ (∧_com (∀ p) a) h0)) x\n        }\n        {assume h0;\n        rewrite ∧_com;\n        have H0: π (`∀ x, a ∧ p x)\n            {assume x;\n            rewrite ∧_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∧_dist_r t a p)) H0\n        };\nend;\n\nopaque symbol ∀∨_dist_r t a (p : τ(t ⤳ o)): π ((a ∨ ∀ p) = (`∀ x, a ∨ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∨ ∀ p) (∀(λ x, a ∨ p x)) _ _\n        {assume h x;\n        refine ∨ₑ h _ _\n            {assume h0;\n            refine ∨ᵢ₁ h0}\n            {assume h0;\n            refine ∨ᵢ₂ (h0 x)}}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∨ᵢ₂ h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            refine ∨ₑ (h (ε (λ x, ¬ (p x)))) _ _\n                {assume h0;\n                refine ∨ᵢ₁ h0}\n                {assume h0;\n                refine ⊥ₑ (H0 h0)}}}\nend;\n\nopaque symbol ∀∨_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∨ a) = (`∀ x,p x ∨ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∨ a) (`∀ x,p x ∨ a) _ _\n        {assume h0 x;\n        rewrite ∨_com;\n        refine (=⇒ ((∀∨_dist_r t a p)) (=⇒ (∨_com (∀ p) a) h0)) x}\n        {assume h0;\n        rewrite ∨_com;\n        have H0: π (`∀ x, a ∨ p x)\n            {assume x;\n            rewrite ∨_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∨_dist_r t a p)) H0};\nend;\n\nopaque symbol ∀_ext [t: Set] p q : π(`∀ (x : τ t), p x = q x) → π ((`∀ (x: τ t), p x) = (`∀ (x: τ t), q x))≔\nbegin\n    assume t p q h;\n    refine propExt (`∀ (x: τ t), p x) (`∀ (x: τ t), q x) _ _\n        {assume h1 x;\n        refine =⇒ (h x) (h1 x)}\n        {assume h1 x;\n        refine =⇒ (eq_sym (h x)) (h1 x)}\nend;\n\n\n/******************************************************************************\n*  Definition of Leo-III clausification tactic        \n******************************************************************************/\n\nsymbol normAsso ≔ #repeat ((#rewrite \"\" \"\" ∧_assoc) #orelse (#rewrite \"\" \"\" ∨_assoc));\n\nsymbol allCNFids_list ≔ ((#rewrite \"\" \"\" deMorgan_∧) ⸬ (#rewrite \"\" \"\" deMorgan_∨) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ □);\n\n//symbol boolIds ≔ #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;\nsymbol boolIds ≔ (#and (applyAny allCNFids_list) normAsso);\n\nsymbol skolemProzess_∃ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∃_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol skolemProzess_∀ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∀_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol tryVars: \uD835\uDD43 string → Tactic; \nrule tryVars ($v0 ⸬ ($v1 ⸬ $vs)) ↪ (#assume $v0) #orelse (tryVars ($v1 ⸬ $vs))\nwith tryVars ($v0 ⸬ □) ↪ (#assume $v0);\n\nsymbol move_∀_out (varList: \uD835\uDD43 string) ≔ #repeat (((#rewrite \"\" \"\" ∀∧_dist_r) #orelse (#rewrite  \"\" \"\" ∀∧_dist_l) #orelse (#rewrite  \"\" \"\" ∀∨_dist_r) #orelse (#rewrite \"\" \"\" ∀∨_dist_l)) #orelse (#and (#and (#refine \"∀_ext _ _ _\") (#simplify))) (tryVars varList));\n\nsymbol move_¬∃_out (varList: \uD835\uDD43 string) ≔ (#and (#rewrite \"\" \"\" ¬∃=∀¬) (move_∀_out varList));\n\nsymbol skolemProzess (allSkolemRW : \uD835\uDD43 tactic) ≔ (skolemProzess_∀ allSkolemRW) #orelse (skolemProzess_∃ allSkolemRW);\n\nsymbol generalizeQuant (varList: \uD835\uDD43 string) ≔ (move_∀_out varList) #orelse (move_¬∃_out varList);\n\nsymbol handleQuants (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ ((skolemProzess_∀ allSkolemRW) #orelse (move_∀_out varList)) #orelse ((move_¬∃_out varList) #orelse (skolemProzess_∃ allSkolemRW));\n\n//symbol cnfTac (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ #repeat ((handleQuants varList allSkolemRW) #orelse boolIds); \nsymbol cnfTac : \uD835\uDD43 string → \uD835\uDD43 tactic → Tactic;\nrule cnfTac □ □ ↪ #and (#repeat boolIds) #reflexivity\nwith cnfTac ($v0 ⸬ $v) □ ↪  #repeat ((generalizeQuant ($v0 ⸬ $v)) #orelse boolIds)\nwith cnfTac □ ($s0 ⸬ $s) ↪  #and (#repeat ((skolemProzess ($s0 ⸬ $s)) #orelse boolIds)) #reflexivity\nwith cnfTac ($v0 ⸬ $v) ($s0 ⸬ $s) ↪ #repeat ((handleQuants ($v0 ⸬ $v) ($s0 ⸬ $s)) #orelse boolIds);"
  //val tempLib: String = "//require open Stdlib.Set Stdlib.Prop Stdlib.PropExt Stdlib.List Stdlib.FOL Stdlib.HOL Stdlib.Impred Stdlib.Eq ;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon Leo-III-lambdapi-lib.EPrules Leo-III-lambdapi-lib.MetaTheorems;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\nrequire open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon;\n\n\n\n/******************************************************************************\n *  Setup for the user defined tactic         \n ******************************************************************************/\n\n constant symbol Tactic : TYPE;\n symbol tactic : Set;\n rule τ tactic ↪ Tactic;\n\n constant symbol String : TYPE;\n builtin \"String\" ≔ String;\n constant symbol string : Set;\n rule τ string ↪ String;\n \n symbol #rewrite : String → String → Π [a], π a → Tactic;\n builtin \"rewrite\" ≔ #rewrite;\n \n symbol #orelse : Tactic → Tactic → Tactic;\n builtin \"orelse\" ≔ #orelse;\n notation #orelse infix left 10000;\n \n symbol #refine : String → Tactic;\n builtin \"refine\" ≔ #refine;\n \n symbol #repeat : Tactic → Tactic;\n builtin \"repeat\" ≔ #repeat;\n \n symbol #fail : Tactic;\n builtin \"fail\" ≔ #fail;\n \n symbol #admit : Tactic;\n builtin \"admit\" ≔ #admit;\n \n symbol #and : Tactic → Tactic → Tactic;\n builtin \"and\" ≔ #and;\n \n symbol #apply : Π [a], π a → Tactic;\n builtin \"apply\" ≔ #apply;\n \n symbol #assume : String → Tactic;\n builtin \"assume\" ≔ #assume;\n \n symbol #generalize : Π [a], π a → Tactic;\n builtin \"generalize\" ≔ #generalize;\n \n symbol #have : String → Π [a], π a → Tactic;\n builtin \"have\" ≔ #have; \n \n symbol #induction : Tactic;\n builtin \"induction\" ≔ #induction; \n \n symbol #remove : Π [a], π a → Tactic;\n builtin \"remove\" ≔ #remove;\n \n symbol #reflexivity : Tactic;\n builtin \"reflexivity\" ≔ #reflexivity;\n \n symbol #set : String → Π [a], π a → Tactic;\n builtin \"set\" ≔ #set;\n \n symbol #simplify : Tactic;\n builtin \"simplify\" ≔ #simplify;\n\n symbol #simplify_beta : Tactic;\n builtin \"simplify rule off\" ≔ #simplify_beta;\n \n symbol #solve : Tactic;\n builtin \"solve\" ≔ #solve;\n \n symbol #symmetry : Tactic;\n builtin \"symmetry\" ≔ #symmetry;\n \n symbol #try : Tactic → Tactic;\n builtin \"try\" ≔ #try;\n \n symbol #why3 : Tactic;\n builtin \"why3\" ≔ #why3; \n\n \n // necessary in order to define the tactics\n protected symbol set0 : Set;\n rule τ set0 ↪ Set;\n \n \n/******************************************************************************\n*  Definition of Leo-III simplification tactic        \n******************************************************************************/\n \n//  symbol applyAny : \uD835\uDD43 tactic → Tactic;\n//  rule applyAny ($t0 ⸬ $tl) ↪ $t0 #orelse (applyAny $tl)\n//  with applyAny □ ↪ #fail;\n\nsymbol applyAny : \uD835\uDD43 tactic → Tactic;\n rule applyAny ($t0 ⸬ ($t1 ⸬ $tl)) ↪ $t0 #orelse (applyAny ($t1 ⸬ $tl))\n with applyAny ($t0 ⸬ □) ↪ $t0;\n \n symbol listOfAllSimpRules ≔ ((#rewrite \"\" \"\" ∨_idem) ⸬ (#rewrite \"\" \"\" em_eq_l) ⸬ (#rewrite \"\" \"\" em_eq_r) ⸬ (#rewrite \"\" \"\" ∨⊤) ⸬ \n     (#rewrite \"\" \"\" ⊤∨) ⸬ (#rewrite \"\" \"\" ∨⊥) ⸬ (#rewrite \"\" \"\" ⊥∨) ⸬ (#rewrite \"\" \"\" ∧_idem) ⸬ (#rewrite \"\" \"\" ∧_contra_r) ⸬ (#rewrite \"\" \"\" ∧_contra_l) ⸬ \n     (#rewrite \"\" \"\" ∧⊤) ⸬ (#rewrite \"\" \"\" ⊤∧) ⸬ (#rewrite \"\" \"\" ∧⊥) ⸬ (#rewrite \"\" \"\" ⊥∧) ⸬ (#rewrite \"\" \"\" ⇒⊤) ⸬ (#rewrite \"\" \"\" ⊥⇒) ⸬ (#rewrite \"\" \"\" ⊤⇒) ⸬ \n     (#rewrite \"\" \"\" ⇒⊥) ⸬ (#rewrite \"\" \"\" ⇒_idem) ⸬ (#rewrite \"\" \"\" ⇔⊤) ⸬ (#rewrite \"\" \"\" ⊤⇔) ⸬ (#rewrite \"\" \"\" ⊥⇔) ⸬ (#rewrite \"\" \"\" ⇔⊥) ⸬ \n     (#rewrite \"\" \"\" ⇔_idem) ⸬ (#rewrite \"\" \"\" ¬⊤) ⸬ (#rewrite \"\" \"\" ¬⊥) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" =⊤) ⸬ (#rewrite \"\" \"\" ⊤=) ⸬ \n     (#rewrite \"\" \"\" =⊥) ⸬ (#rewrite \"\" \"\" ⊥=) ⸬ (#rewrite \"\" \"\" =_idem) ⸬ (#rewrite \"\" \"\" ¬=⊥) ⸬ (#rewrite \"\" \"\" ¬⊥=) ⸬ (#rewrite \"\" \"\" ¬=⊤) ⸬ \n     (#rewrite \"\" \"\" ¬⊤=) ⸬ (#rewrite \"\" \"\" ¬=_idem) ⸬ (#rewrite \"\" \"\" ∀_const) ⸬ (#rewrite \"\" \"\" ∃_const) ⸬ (#rewrite \"\" \"\" polarity_switch) ⸬ (#refine \"⊤ᵢ\") ⸬ □);\n \n symbol applyAllSimplifications ≔ #repeat (applyAny listOfAllSimpRules);\n\n\n/******************************************************************************\n*  Definition of additional rules for clausification      \n******************************************************************************/\n\nopaque symbol ¬∀=∃¬ (t : Set) (p : τ (t ⤳ o)) : //lemma6\nπ (¬(∀ p) = (`∃ (x : τ t), ¬ (p x)))≔\nbegin\nassume t p;\nrefine propExt (¬ (∀ p)) (`∃ x, ¬ (p x)) _ _\n{assume h;\n    refine ∨ₑ (em (`∃ x, ¬ p x)) _ _\n    {assume he; refine he}\n    {assume hne;\n        have forall_p : Π x : τ t, π (p x)\n            {assume a; refine ¬¬ₑ (p a) (λ hp, hne (∃ᵢ [t] [λ y, ¬ p y] a hp))};\n        refine ⊥ₑ (h (λ a, forall_p a))}}\n{assume h h2;\n    refine ∃ₑ [t] [λ y, ¬ p y] h (λ a hna, hna (h2 a))}\nend;\n\nopaque symbol ¬∃=∀¬ (t : Set) (p : τ (t ⤳ o)) : // lemma7\nπ (¬(∃ p) = (`∀ (x : τ t), ¬ p x))≔     \nbegin\nassume t p;\nrefine propExt (¬ (∃ p)) (`∀ x, ¬ p x) _ _\n{assume h a ha; refine h (∃ᵢ [t] [p] a ha)}\n{assume h1 h2; refine ∃ₑ [t] [p] h2 (λ a ha, (h1 a) ha)}\nend;\n\n\n//  Skolemisazion\n\n\nopaque symbol εᵢ_rev :  Π [a: Set], Π p: (τ a → Prop),  π (p (ε p)) → π (∃ p)≔\nbegin\nassume a p h;\nrefine ∃ᵢ [a] [p] (ε p) h\nend;\n\nopaque symbol ∃_skolem (a: Set) (p: τ (a ⤳ o)) :  \n π ((∃ p) = (p (ε p)))≔\nbegin\n assume a p;\n refine propExt (∃ p) (p (ε p)) (εᵢ [a] p) (εᵢ_rev [a] p)\nend;\n\nopaque symbol ∀_skolem (a: Set) (p: τ (a ⤳ o)) :  \nπ (¬ (∀ p) = ¬ (p (ε (λ x, ¬ (p x)))))≔\nbegin\nassume a p;\nrewrite ¬∀=∃¬;\nrefine  propExt (`∃ x, ¬ (p x)) (¬ (p (ε (λ x, ¬ (p x))))) _ _\n    {assume h; refine ind_eq (eq_sym (∃_skolem a (λ x, ¬ (p x)))) (λ x, x) h}\n    {assume h; refine ind_eq (∃_skolem a (λ x, ¬ (p x))) (λ x, x) h}\nend;\n\n\n//Quantifier Distributivity\n\nopaque symbol ∀∧_dist_r t a (p : τ(t ⤳ o)): π ((a ∧ ∀ p) = (`∀ x, a ∧ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∧ ∀ p) (∀(λ x, a ∧ p x)) _ _\n        {assume h x;\n        refine ∧ᵢ (∧ₑ₁ h) ((∧ₑ₂ h) x)}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∧ᵢ (∧ₑ₁ (h (el t))) h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            have H1: π (p (ε (λ x, ¬ (p x))))\n                {refine ∧ₑ₂ (h (ε (λ x, ¬ (p x))))};\n            refine ⊥ₑ (H0 H1)}}\nend;\n\nopaque symbol ∀∧_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∧ a) = (`∀ x,p x ∧ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∧ a) (`∀ x, p x ∧ a) _ _\n        {assume h0 x;\n        rewrite ∧_com;\n        refine (=⇒ ((∀∧_dist_r t a p)) (=⇒ (∧_com (∀ p) a) h0)) x\n        }\n        {assume h0;\n        rewrite ∧_com;\n        have H0: π (`∀ x, a ∧ p x)\n            {assume x;\n            rewrite ∧_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∧_dist_r t a p)) H0\n        };\nend;\n\nopaque symbol ∀∨_dist_r t a (p : τ(t ⤳ o)): π ((a ∨ ∀ p) = (`∀ x, a ∨ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∨ ∀ p) (∀(λ x, a ∨ p x)) _ _\n        {assume h x;\n        refine ∨ₑ h _ _\n            {assume h0;\n            refine ∨ᵢ₁ h0}\n            {assume h0;\n            refine ∨ᵢ₂ (h0 x)}}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∨ᵢ₂ h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            refine ∨ₑ (h (ε (λ x, ¬ (p x)))) _ _\n                {assume h0;\n                refine ∨ᵢ₁ h0}\n                {assume h0;\n                refine ⊥ₑ (H0 h0)}}}\nend;\n\nopaque symbol ∀∨_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∨ a) = (`∀ x,p x ∨ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∨ a) (`∀ x,p x ∨ a) _ _\n        {assume h0 x;\n        rewrite ∨_com;\n        refine (=⇒ ((∀∨_dist_r t a p)) (=⇒ (∨_com (∀ p) a) h0)) x}\n        {assume h0;\n        rewrite ∨_com;\n        have H0: π (`∀ x, a ∨ p x)\n            {assume x;\n            rewrite ∨_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∨_dist_r t a p)) H0};\nend;\n\nopaque symbol ∀_ext [t: Set] p q : π(`∀ (x : τ t), p x = q x) → π ((`∀ (x: τ t), p x) = (`∀ (x: τ t), q x))≔\nbegin\n    assume t p q h;\n    refine propExt (`∀ (x: τ t), p x) (`∀ (x: τ t), q x) _ _\n        {assume h1 x;\n        refine =⇒ (h x) (h1 x)}\n        {assume h1 x;\n        refine =⇒ (eq_sym (h x)) (h1 x)}\nend;\n\n\n/******************************************************************************\n*  Definition of Leo-III clausification tactic        \n******************************************************************************/\n\nsymbol normAsso ≔ #repeat ((#rewrite \"\" \"\" ∧_assoc) #orelse (#rewrite \"\" \"\" ∨_assoc));\n\nsymbol normAsso_∨ ≔ #repeat (#rewrite \"\" \"\" ∨_assoc);\n\nsymbol normAsso_∧ ≔ #repeat (#rewrite \"\" \"\" ∧_assoc);\n\n//symbol allCNFids_list ≔ ((#and (#rewrite \"\" \"\" deMorgan_∧) normAsso_∨) ⸬ (#and (#rewrite \"\" \"\" deMorgan_∨) ) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ □);\n\nsymbol allCNFids_list ≔ ((#rewrite \"\" \"\" deMorgan_∧) ⸬ (#rewrite \"\" \"\" deMorgan_∨) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" ∨_assoc) ⸬ (#rewrite \"\" \"\" ∧_assoc) ⸬ □);\n\n\n//symbol boolIds ≔ #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;\nsymbol boolIds ≔ (#and (applyAny allCNFids_list) normAsso);\n// #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;\n\nsymbol skolemProzess_∃ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∃_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol skolemProzess_∀ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∀_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol tryVars: \uD835\uDD43 string → Tactic; \nrule tryVars ($v0 ⸬ ($v1 ⸬ $vs)) ↪ (#assume $v0) #orelse (tryVars ($v1 ⸬ $vs))\nwith tryVars ($v0 ⸬ □) ↪ (#assume $v0);\n\nsymbol move_∀_out (varList: \uD835\uDD43 string) ≔ #repeat (((#rewrite \"\" \"\" ∀∧_dist_r) #orelse (#rewrite  \"\" \"\" ∀∧_dist_l) #orelse (#rewrite  \"\" \"\" ∀∨_dist_r) #orelse (#rewrite \"\" \"\" ∀∨_dist_l)) #orelse (#and (#and (#refine \"∀_ext _ _ _\") (#simplify))) (tryVars varList));\n\nsymbol move_¬∃_out (varList: \uD835\uDD43 string) ≔ (#and (#rewrite \"\" \"\" ¬∃=∀¬) (move_∀_out varList));\n\nsymbol skolemProzess (allSkolemRW : \uD835\uDD43 tactic) ≔ (skolemProzess_∀ allSkolemRW) #orelse (skolemProzess_∃ allSkolemRW);\n\nsymbol generalizeQuant (varList: \uD835\uDD43 string) ≔ (move_∀_out varList) #orelse (move_¬∃_out varList);\n\nsymbol handleQuants (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ ((skolemProzess_∀ allSkolemRW) #orelse (move_∀_out varList)) #orelse ((move_¬∃_out varList) #orelse (skolemProzess_∃ allSkolemRW));\n\n//symbol cnfTac (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ #repeat ((handleQuants varList allSkolemRW) #orelse boolIds); \nsymbol cnfTac : \uD835\uDD43 string → \uD835\uDD43 tactic → Tactic;\nrule cnfTac □ □ ↪ #and (#repeat boolIds) #reflexivity\nwith cnfTac ($v0 ⸬ $v) □ ↪  #repeat ((generalizeQuant ($v0 ⸬ $v)) #orelse boolIds)\nwith cnfTac □ ($s0 ⸬ $s) ↪  #and (#repeat ((skolemProzess ($s0 ⸬ $s)) #orelse boolIds)) #reflexivity\nwith cnfTac ($v0 ⸬ $v) ($s0 ⸬ $s) ↪ #repeat ((handleQuants ($v0 ⸬ $v) ($s0 ⸬ $s)) #orelse boolIds);"
  //val tempLib: String = "//require open Stdlib.Set Stdlib.Prop Stdlib.PropExt Stdlib.List Stdlib.FOL Stdlib.HOL Stdlib.Impred Stdlib.Eq ;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon Leo-III-lambdapi-lib.EPrules Leo-III-lambdapi-lib.MetaTheorems;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\nrequire open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon;\n\n\n\n/******************************************************************************\n *  Setup for the user defined tactic         \n ******************************************************************************/\n\n constant symbol Tactic : TYPE;\n symbol tactic : Set;\n rule τ tactic ↪ Tactic;\n\n constant symbol String : TYPE;\n builtin \"String\" ≔ String;\n constant symbol string : Set;\n rule τ string ↪ String;\n \n symbol #rewrite : String → String → Π [a], π a → Tactic;\n builtin \"rewrite\" ≔ #rewrite;\n \n symbol #orelse : Tactic → Tactic → Tactic;\n builtin \"orelse\" ≔ #orelse;\n notation #orelse infix left 10000;\n \n symbol #refine : String → Tactic;\n builtin \"refine\" ≔ #refine;\n \n symbol #repeat : Tactic → Tactic;\n builtin \"repeat\" ≔ #repeat;\n \n symbol #fail : Tactic;\n builtin \"fail\" ≔ #fail;\n \n symbol #admit : Tactic;\n builtin \"admit\" ≔ #admit;\n \n symbol #and : Tactic → Tactic → Tactic;\n builtin \"and\" ≔ #and;\n \n symbol #apply : Π [a], π a → Tactic;\n builtin \"apply\" ≔ #apply;\n \n symbol #assume : String → Tactic;\n builtin \"assume\" ≔ #assume;\n \n symbol #generalize : Π [a], π a → Tactic;\n builtin \"generalize\" ≔ #generalize;\n \n symbol #have : String → Π [a], π a → Tactic;\n builtin \"have\" ≔ #have; \n \n symbol #induction : Tactic;\n builtin \"induction\" ≔ #induction; \n \n symbol #remove : Π [a], π a → Tactic;\n builtin \"remove\" ≔ #remove;\n \n symbol #reflexivity : Tactic;\n builtin \"reflexivity\" ≔ #reflexivity;\n \n symbol #set : String → Π [a], π a → Tactic;\n builtin \"set\" ≔ #set;\n \n symbol #simplify : Tactic;\n builtin \"simplify\" ≔ #simplify;\n\n symbol #simplify_beta : Tactic;\n builtin \"simplify rule off\" ≔ #simplify_beta;\n \n symbol #solve : Tactic;\n builtin \"solve\" ≔ #solve;\n \n symbol #symmetry : Tactic;\n builtin \"symmetry\" ≔ #symmetry;\n \n symbol #try : Tactic → Tactic;\n builtin \"try\" ≔ #try;\n \n symbol #why3 : Tactic;\n builtin \"why3\" ≔ #why3; \n\n \n // necessary in order to define the tactics\n protected symbol set0 : Set;\n rule τ set0 ↪ Set;\n \n \n/******************************************************************************\n*  Definition of Leo-III simplification tactic        \n******************************************************************************/\n \n//  symbol applyAny : \uD835\uDD43 tactic → Tactic;\n//  rule applyAny ($t0 ⸬ $tl) ↪ $t0 #orelse (applyAny $tl)\n//  with applyAny □ ↪ #fail;\n\nsymbol applyAny : \uD835\uDD43 tactic → Tactic;\n rule applyAny ($t0 ⸬ ($t1 ⸬ $tl)) ↪ $t0 #orelse (applyAny ($t1 ⸬ $tl))\n with applyAny ($t0 ⸬ □) ↪ $t0;\n \n symbol listOfAllSimpRules ≔ ((#rewrite \"\" \"\" ∨_idem) ⸬ (#rewrite \"\" \"\" em_eq_l) ⸬ (#rewrite \"\" \"\" em_eq_r) ⸬ (#rewrite \"\" \"\" ∨⊤) ⸬ \n     (#rewrite \"\" \"\" ⊤∨) ⸬ (#rewrite \"\" \"\" ∨⊥) ⸬ (#rewrite \"\" \"\" ⊥∨) ⸬ (#rewrite \"\" \"\" ∧_idem) ⸬ (#rewrite \"\" \"\" ∧_contra_r) ⸬ (#rewrite \"\" \"\" ∧_contra_l) ⸬ \n     (#rewrite \"\" \"\" ∧⊤) ⸬ (#rewrite \"\" \"\" ⊤∧) ⸬ (#rewrite \"\" \"\" ∧⊥) ⸬ (#rewrite \"\" \"\" ⊥∧) ⸬ (#rewrite \"\" \"\" ⇒⊤) ⸬ (#rewrite \"\" \"\" ⊥⇒) ⸬ (#rewrite \"\" \"\" ⊤⇒) ⸬ \n     (#rewrite \"\" \"\" ⇒⊥) ⸬ (#rewrite \"\" \"\" ⇒_idem) ⸬ (#rewrite \"\" \"\" ⇔⊤) ⸬ (#rewrite \"\" \"\" ⊤⇔) ⸬ (#rewrite \"\" \"\" ⊥⇔) ⸬ (#rewrite \"\" \"\" ⇔⊥) ⸬ \n     (#rewrite \"\" \"\" ⇔_idem) ⸬ (#rewrite \"\" \"\" ¬⊤) ⸬ (#rewrite \"\" \"\" ¬⊥) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" =⊤) ⸬ (#rewrite \"\" \"\" ⊤=) ⸬ \n     (#rewrite \"\" \"\" =⊥) ⸬ (#rewrite \"\" \"\" ⊥=) ⸬ (#rewrite \"\" \"\" =_idem) ⸬ (#rewrite \"\" \"\" ¬=⊥) ⸬ (#rewrite \"\" \"\" ¬⊥=) ⸬ (#rewrite \"\" \"\" ¬=⊤) ⸬ \n     (#rewrite \"\" \"\" ¬⊤=) ⸬ (#rewrite \"\" \"\" ¬=_idem) ⸬ (#rewrite \"\" \"\" ∀_const) ⸬ (#rewrite \"\" \"\" ∃_const) ⸬ (#rewrite \"\" \"\" polarity_switch) ⸬ (#refine \"⊤ᵢ\") ⸬ □);\n \n symbol applyAllSimplifications ≔ #repeat (applyAny listOfAllSimpRules);\n\n\n/******************************************************************************\n*  Definition of additional rules for clausification      \n******************************************************************************/\n\nopaque symbol ¬∀=∃¬ (t : Set) (p : τ (t ⤳ o)) : //lemma6\nπ (¬(∀ p) = (`∃ (x : τ t), ¬ (p x)))≔\nbegin\nassume t p;\nrefine propExt (¬ (∀ p)) (`∃ x, ¬ (p x)) _ _\n{assume h;\n    refine ∨ₑ (em (`∃ x, ¬ p x)) _ _\n    {assume he; refine he}\n    {assume hne;\n        have forall_p : Π x : τ t, π (p x)\n            {assume a; refine ¬¬ₑ (p a) (λ hp, hne (∃ᵢ [t] [λ y, ¬ p y] a hp))};\n        refine ⊥ₑ (h (λ a, forall_p a))}}\n{assume h h2;\n    refine ∃ₑ [t] [λ y, ¬ p y] h (λ a hna, hna (h2 a))}\nend;\n\nopaque symbol ¬∃=∀¬ (t : Set) (p : τ (t ⤳ o)) : // lemma7\nπ (¬(∃ p) = (`∀ (x : τ t), ¬ p x))≔     \nbegin\nassume t p;\nrefine propExt (¬ (∃ p)) (`∀ x, ¬ p x) _ _\n{assume h a ha; refine h (∃ᵢ [t] [p] a ha)}\n{assume h1 h2; refine ∃ₑ [t] [p] h2 (λ a ha, (h1 a) ha)}\nend;\n\n\n//  Skolemisazion\n\n\nopaque symbol εᵢ_rev :  Π [a: Set], Π p: (τ a → Prop),  π (p (ε p)) → π (∃ p)≔\nbegin\nassume a p h;\nrefine ∃ᵢ [a] [p] (ε p) h\nend;\n\nopaque symbol ∃_skolem (a: Set) (p: τ (a ⤳ o)) :  \n π ((∃ p) = (p (ε p)))≔\nbegin\n assume a p;\n refine propExt (∃ p) (p (ε p)) (εᵢ [a] p) (εᵢ_rev [a] p)\nend;\n\nopaque symbol ∀_skolem (a: Set) (p: τ (a ⤳ o)) :  \nπ (¬ (∀ p) = ¬ (p (ε (λ x, ¬ (p x)))))≔\nbegin\nassume a p;\nrewrite ¬∀=∃¬;\nrefine  propExt (`∃ x, ¬ (p x)) (¬ (p (ε (λ x, ¬ (p x))))) _ _\n    {assume h; refine ind_eq (eq_sym (∃_skolem a (λ x, ¬ (p x)))) (λ x, x) h}\n    {assume h; refine ind_eq (∃_skolem a (λ x, ¬ (p x))) (λ x, x) h}\nend;\n\n\n//Quantifier Distributivity\n\nopaque symbol ∀∧_dist_r t a (p : τ(t ⤳ o)): π ((a ∧ ∀ p) = (`∀ x, a ∧ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∧ ∀ p) (∀(λ x, a ∧ p x)) _ _\n        {assume h x;\n        refine ∧ᵢ (∧ₑ₁ h) ((∧ₑ₂ h) x)}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∧ᵢ (∧ₑ₁ (h (el t))) h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            have H1: π (p (ε (λ x, ¬ (p x))))\n                {refine ∧ₑ₂ (h (ε (λ x, ¬ (p x))))};\n            refine ⊥ₑ (H0 H1)}}\nend;\n\nopaque symbol ∀∧_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∧ a) = (`∀ x,p x ∧ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∧ a) (`∀ x, p x ∧ a) _ _\n        {assume h0 x;\n        rewrite ∧_com;\n        refine (=⇒ ((∀∧_dist_r t a p)) (=⇒ (∧_com (∀ p) a) h0)) x\n        }\n        {assume h0;\n        rewrite ∧_com;\n        have H0: π (`∀ x, a ∧ p x)\n            {assume x;\n            rewrite ∧_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∧_dist_r t a p)) H0\n        };\nend;\n\nopaque symbol ∀∨_dist_r t a (p : τ(t ⤳ o)): π ((a ∨ ∀ p) = (`∀ x, a ∨ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∨ ∀ p) (∀(λ x, a ∨ p x)) _ _\n        {assume h x;\n        refine ∨ₑ h _ _\n            {assume h0;\n            refine ∨ᵢ₁ h0}\n            {assume h0;\n            refine ∨ᵢ₂ (h0 x)}}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∨ᵢ₂ h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            refine ∨ₑ (h (ε (λ x, ¬ (p x)))) _ _\n                {assume h0;\n                refine ∨ᵢ₁ h0}\n                {assume h0;\n                refine ⊥ₑ (H0 h0)}}}\nend;\n\nopaque symbol ∀∨_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∨ a) = (`∀ x,p x ∨ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∨ a) (`∀ x,p x ∨ a) _ _\n        {assume h0 x;\n        rewrite ∨_com;\n        refine (=⇒ ((∀∨_dist_r t a p)) (=⇒ (∨_com (∀ p) a) h0)) x}\n        {assume h0;\n        rewrite ∨_com;\n        have H0: π (`∀ x, a ∨ p x)\n            {assume x;\n            rewrite ∨_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∨_dist_r t a p)) H0};\nend;\n\nopaque symbol ∀_ext [t: Set] p q : π(`∀ (x : τ t), p x = q x) → π ((`∀ (x: τ t), p x) = (`∀ (x: τ t), q x))≔\nbegin\n    assume t p q h;\n    refine propExt (`∀ (x: τ t), p x) (`∀ (x: τ t), q x) _ _\n        {assume h1 x;\n        refine =⇒ (h x) (h1 x)}\n        {assume h1 x;\n        refine =⇒ (eq_sym (h x)) (h1 x)}\nend;\n\n\n/******************************************************************************\n*  Definition of Leo-III clausification tactic        \n******************************************************************************/\n\nsymbol normAsso ≔ #repeat ((#rewrite \"\" \"\" ∧_assoc) #orelse (#rewrite \"\" \"\" ∨_assoc));\n\nsymbol normAsso_∨ ≔ #repeat (#rewrite \"\" \"\" ∨_assoc);\n\nsymbol normAsso_∧ ≔ #repeat (#rewrite \"\" \"\" ∧_assoc);\n\n//symbol allCNFids_list ≔ ((#and (#rewrite \"\" \"\" deMorgan_∧) normAsso_∨) ⸬ (#and (#rewrite \"\" \"\" deMorgan_∨) ) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ □);\n\nsymbol allCNFids_list ≔ ((#rewrite \"\" \"\" deMorgan_∧) ⸬ (#rewrite \"\" \"\" deMorgan_∨) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" ∨_assoc) ⸬ (#rewrite \"\" \"\" ∧_assoc) ⸬ □);\n\n\n//symbol boolIds ≔ #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;\nsymbol boolIds ≔ (#and (applyAny allCNFids_list) normAsso);\n// #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;\n\nsymbol skolemProzess_∃ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∃_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol skolemProzess_∀ (allSkolemRW : \uD835\uDD43 tactic) ≔ #and (#and (#rewrite \"\" \"\" ∀_skolem) (applyAny allSkolemRW)) #simplify_beta;\n\nsymbol tryVars: \uD835\uDD43 string → Tactic; \nrule tryVars ($v0 ⸬ ($v1 ⸬ $vs)) ↪ (#assume $v0) #orelse (tryVars ($v1 ⸬ $vs))\nwith tryVars ($v0 ⸬ □) ↪ (#assume $v0);\n\nsymbol move_∀_out (varList: \uD835\uDD43 string) ≔ #repeat (((#rewrite \"\" \"\" ∀∧_dist_r) #orelse (#rewrite  \"\" \"\" ∀∧_dist_l) #orelse (#rewrite  \"\" \"\" ∀∨_dist_r) #orelse (#rewrite \"\" \"\" ∀∨_dist_l)) #orelse (#and (#and (#refine \"∀_ext _ _ _\") (#simplify))) (tryVars varList));\n\nsymbol move_¬∃_out (varList: \uD835\uDD43 string) ≔ (#and (#rewrite \"\" \"\" ¬∃=∀¬) (move_∀_out varList));\n\nsymbol skolemProzess (allSkolemRW : \uD835\uDD43 tactic) ≔ (skolemProzess_∀ allSkolemRW) #orelse (skolemProzess_∃ allSkolemRW);\n\nsymbol generalizeQuant (varList: \uD835\uDD43 string) ≔ (move_∀_out varList) #orelse (move_¬∃_out varList);\n\nsymbol handleQuants (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ ((skolemProzess_∀ allSkolemRW) #orelse (move_∀_out varList)) #orelse ((move_¬∃_out varList) #orelse (skolemProzess_∃ allSkolemRW));\n\n//symbol cnfTac (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ #repeat ((handleQuants varList allSkolemRW) #orelse boolIds); \n// symbol cnfTac : \uD835\uDD43 string → \uD835\uDD43 tactic → Tactic;\n// rule cnfTac □ □ ↪ #and (#repeat boolIds) #reflexivity\n// with cnfTac ($v0 ⸬ $v) □ ↪  #repeat ((generalizeQuant ($v0 ⸬ $v)) #orelse boolIds)\n// with cnfTac □ ($s0 ⸬ $s) ↪  #and (#repeat ((skolemProzess ($s0 ⸬ $s)) #orelse boolIds)) #reflexivity\n// with cnfTac ($v0 ⸬ $v) ($s0 ⸬ $s) ↪ #repeat ((handleQuants ($v0 ⸬ $v) ($s0 ⸬ $s)) #orelse boolIds);\n\n// we need to do one skolem Term at the time \n// so the process should be a bit like \n// 1. repeat bool id-steps until you can not do anythig anymore\n// 2. do skolem process for first sk. term\n// 3. repeat bool id-step until you can not do anything anymore\n// 4. do skolem process for second sk. term \n// ...\n// n. do reflexivity\n\nsymbol skolemProzess_∃_new sk_def : Tactic ≔ #and (#and (#rewrite \"\" \"\" ∃_skolem) sk_def) #simplify_beta;\n\nsymbol skolemProzess_∀_new sk_def : Tactic ≔ #and (#and (#rewrite \"\" \"\" ∀_skolem) sk_def) #simplify_beta;\n\nsymbol skolemProzess_new sk_def : Tactic ≔ (skolemProzess_∀_new sk_def) #orelse (skolemProzess_∃_new sk_def);\n\nsymbol stepwise_skolem: \uD835\uDD43 tactic → Tactic;\nrule stepwise_skolem ($sk1 ⸬ ($sk2 ⸬ $sk3)) ↪ #and (#and (#repeat boolIds) (skolemProzess_new $sk1)) (stepwise_skolem ($sk2 ⸬ $sk3))\nwith stepwise_skolem ($sk1 ⸬ □) ↪ #and (#and (#and (#repeat boolIds) (skolemProzess_new $sk1)) (#repeat boolIds)) #reflexivity;\n\n\nsymbol cnfTac : \uD835\uDD43 string → \uD835\uDD43 tactic → Tactic;\nrule cnfTac □ □ ↪ #and (#repeat boolIds) #reflexivity\nwith cnfTac ($v0 ⸬ $v) □ ↪  #repeat ((generalizeQuant ($v0 ⸬ $v)) #orelse boolIds)\nwith cnfTac □ ($s0 ⸬ $s) ↪  stepwise_skolem ($s0 ⸬ $s)\nwith cnfTac ($v0 ⸬ $v) ($s0 ⸬ $s) ↪ #repeat ((handleQuants ($v0 ⸬ $v) ($s0 ⸬ $s)) #orelse boolIds);"
  val tempLib: String = "//require open Stdlib.Set Stdlib.Prop Stdlib.PropExt Stdlib.List Stdlib.FOL Stdlib.HOL Stdlib.Impred Stdlib.Eq ;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon Leo-III-lambdapi-lib.EPrules Leo-III-lambdapi-lib.MetaTheorems;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\n//require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List;\nrequire open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon;\n\n\n\n/******************************************************************************\n *  Setup for the user defined tactic         \n ******************************************************************************/\n\n constant symbol Tactic : TYPE;\n symbol tactic : Set;\n rule τ tactic ↪ Tactic;\n\n constant symbol String : TYPE;\n builtin \"String\" ≔ String;\n constant symbol string : Set;\n rule τ string ↪ String;\n \n symbol #rewrite : String → String → Π [a], π a → Tactic;\n builtin \"rewrite\" ≔ #rewrite;\n \n symbol #orelse : Tactic → Tactic → Tactic;\n builtin \"orelse\" ≔ #orelse;\n notation #orelse infix left 10000;\n \n symbol #refine : String → Tactic;\n builtin \"refine\" ≔ #refine;\n \n symbol #repeat : Tactic → Tactic;\n builtin \"repeat\" ≔ #repeat;\n \n symbol #fail : Tactic;\n builtin \"fail\" ≔ #fail;\n \n symbol #admit : Tactic;\n builtin \"admit\" ≔ #admit;\n \n symbol #and : Tactic → Tactic → Tactic;\n builtin \"and\" ≔ #and;\n \n symbol #apply : Π [a], π a → Tactic;\n builtin \"apply\" ≔ #apply;\n \n symbol #assume : String → Tactic;\n builtin \"assume\" ≔ #assume;\n \n symbol #generalize : Π [a], π a → Tactic;\n builtin \"generalize\" ≔ #generalize;\n \n symbol #have : String → Π [a], π a → Tactic;\n builtin \"have\" ≔ #have; \n \n symbol #induction : Tactic;\n builtin \"induction\" ≔ #induction; \n \n symbol #remove : Π [a], π a → Tactic;\n builtin \"remove\" ≔ #remove;\n \n symbol #reflexivity : Tactic;\n builtin \"reflexivity\" ≔ #reflexivity;\n \n symbol #set : String → Π [a], π a → Tactic;\n builtin \"set\" ≔ #set;\n \n symbol #simplify : Tactic;\n builtin \"simplify\" ≔ #simplify;\n\n symbol #simplify_beta : Tactic;\n builtin \"simplify rule off\" ≔ #simplify_beta;\n \n symbol #solve : Tactic;\n builtin \"solve\" ≔ #solve;\n \n symbol #symmetry : Tactic;\n builtin \"symmetry\" ≔ #symmetry;\n \n symbol #try : Tactic → Tactic;\n builtin \"try\" ≔ #try;\n \n symbol #why3 : Tactic;\n builtin \"why3\" ≔ #why3; \n\n symbol #change : Tactic;\n builtin \"change\" ≔ #change;\n\n \n // necessary in order to define the tactics\n protected symbol set0 : Set;\n rule τ set0 ↪ Set;\n \n \n/******************************************************************************\n*  Definition of Leo-III simplification tactic        \n******************************************************************************/\n\nopaque symbol ¬x=_idem : Π x, π (((¬ x) = x) = ⊥)≔\nbegin\n    assume x;\n    refine propExt ((¬ x )= x) ⊥ _ _\n        {assume h; \n        refine ∨ₑ [x] [¬ x] [⊥] (em x) _ _\n            {assume h0;\n            refine =⇒ (eq_sym h) h0 h0}\n            {assume h0;\n            refine h0 (=⇒ h h0)}}\n        {assume h;\n        refine ⊥ₑ h}\nend;\n\nopaque symbol =¬x_idem : Π x, π ((x = (¬ x)) = ⊥)≔\nbegin\n    assume x;\n    rewrite =_sym x (¬ x);\n    refine ¬x=_idem x\nend;\n \nsymbol applyAny : \uD835\uDD43 tactic → Tactic;\n rule applyAny ($t0 ⸬ ($t1 ⸬ $tl)) ↪ $t0 #orelse (applyAny ($t1 ⸬ $tl))\n with applyAny ($t0 ⸬ □) ↪ $t0;\n \n symbol listOfAllSimpRules ≔ ((#rewrite \"\" \"\" ∨_idem) ⸬ (#rewrite \"\" \"\" em_eq_l) ⸬ (#rewrite \"\" \"\" em_eq_r) ⸬ (#rewrite \"\" \"\" ∨⊤) ⸬ \n     (#rewrite \"\" \"\" ⊤∨) ⸬ (#rewrite \"\" \"\" ∨⊥) ⸬ (#rewrite \"\" \"\" ⊥∨) ⸬ (#rewrite \"\" \"\" ∧_idem) ⸬ (#rewrite \"\" \"\" ∧_contra_r) ⸬ (#rewrite \"\" \"\" ∧_contra_l) ⸬ \n     (#rewrite \"\" \"\" ∧⊤) ⸬ (#rewrite \"\" \"\" ⊤∧) ⸬ (#rewrite \"\" \"\" ∧⊥) ⸬ (#rewrite \"\" \"\" ⊥∧) ⸬ (#rewrite \"\" \"\" ⇒⊤) ⸬ (#rewrite \"\" \"\" ⊥⇒) ⸬ (#rewrite \"\" \"\" ⊤⇒) ⸬ \n     (#rewrite \"\" \"\" ⇒⊥) ⸬ (#rewrite \"\" \"\" ⇒_idem) ⸬ (#rewrite \"\" \"\" ⇔⊤) ⸬ (#rewrite \"\" \"\" ⊤⇔) ⸬ (#rewrite \"\" \"\" ⊥⇔) ⸬ (#rewrite \"\" \"\" ⇔⊥) ⸬ \n     (#rewrite \"\" \"\" ⇔_idem) ⸬ (#rewrite \"\" \"\" ¬⊤) ⸬ (#rewrite \"\" \"\" ¬⊥) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" =⊤) ⸬ (#rewrite \"\" \"\" ⊤=) ⸬ \n     (#rewrite \"\" \"\" =⊥) ⸬ (#rewrite \"\" \"\" ⊥=) ⸬ (#rewrite \"\" \"\" =_idem) ⸬ (#rewrite \"\" \"\" ¬=⊥) ⸬ (#rewrite \"\" \"\" ¬⊥=) ⸬ (#rewrite \"\" \"\" ¬=⊤) ⸬ \n     (#rewrite \"\" \"\" ¬⊤=) ⸬ (#rewrite \"\" \"\" ¬=_idem) ⸬ (#rewrite \"\" \"\" ∀_const) ⸬ (#rewrite \"\" \"\" ∃_const) ⸬ (#rewrite \"\" \"\" ¬x=_idem) ⸬ (#rewrite \"\" \"\" =¬x_idem) ⸬ \n     (#rewrite \"\" \"\" polarity_switch) ⸬ (#refine \"⊤ᵢ\") ⸬ □);\n     // the rules and ... are added as Leo omits trivially false literals, we account for this using this rule\n \n symbol applyAllSimplifications ≔ #repeat (applyAny listOfAllSimpRules);\n\n\n/******************************************************************************\n*  Definition of additional rules for clausification      \n******************************************************************************/\n\nopaque symbol ¬∀=∃¬ (t : Set) (p : τ (t ⤳ o)) : //lemma6\nπ (¬(∀ p) = (`∃ (x : τ t), ¬ (p x)))≔\nbegin\nassume t p;\nrefine propExt (¬ (∀ p)) (`∃ x, ¬ (p x)) _ _\n{assume h;\n    refine ∨ₑ (em (`∃ x, ¬ p x)) _ _\n    {assume he; refine he}\n    {assume hne;\n        have forall_p : Π x : τ t, π (p x)\n            {assume a; refine ¬¬ₑ (p a) (λ hp, hne (∃ᵢ [t] [λ y, ¬ p y] a hp))};\n        refine ⊥ₑ (h (λ a, forall_p a))}}\n{assume h h2;\n    refine ∃ₑ [t] [λ y, ¬ p y] h (λ a hna, hna (h2 a))}\nend;\n\nopaque symbol ¬∃=∀¬ (t : Set) (p : τ (t ⤳ o)) : // lemma7\nπ (¬(∃ p) = (`∀ (x : τ t), ¬ p x))≔     \nbegin\nassume t p;\nrefine propExt (¬ (∃ p)) (`∀ x, ¬ p x) _ _\n{assume h a ha; refine h (∃ᵢ [t] [p] a ha)}\n{assume h1 h2; refine ∃ₑ [t] [p] h2 (λ a ha, (h1 a) ha)}\nend;\n\n\n//  Skolemisazion\n\n\nopaque symbol εᵢ_rev :  Π [a: Set], Π p: (τ a → Prop),  π (p (ε p)) → π (∃ p)≔\nbegin\nassume a p h;\nrefine ∃ᵢ [a] [p] (ε p) h\nend;\n\nopaque symbol ∃_skolem (a: Set) (p: τ (a ⤳ o)) :  \n π ((∃ p) = (p (ε p)))≔\nbegin\n assume a p;\n refine propExt (∃ p) (p (ε p)) (εᵢ [a] p) (εᵢ_rev [a] p)\nend;\n\nopaque symbol ∀_skolem (a: Set) (p: τ (a ⤳ o)) :  \nπ (¬ (∀ p) = ¬ (p (ε (λ x, ¬ (p x)))))≔\nbegin\nassume a p;\nrewrite ¬∀=∃¬;\nrefine  propExt (`∃ x, ¬ (p x)) (¬ (p (ε (λ x, ¬ (p x))))) _ _\n    {assume h; refine ind_eq (eq_sym (∃_skolem a (λ x, ¬ (p x)))) (λ x, x) h}\n    {assume h; refine ind_eq (∃_skolem a (λ x, ¬ (p x))) (λ x, x) h}\nend;\n\n\n//Quantifier Distributivity\n\nopaque symbol ∀∧_dist_r t a (p : τ(t ⤳ o)): π ((a ∧ ∀ p) = (`∀ x, a ∧ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∧ ∀ p) (∀(λ x, a ∧ p x)) _ _\n        {assume h x;\n        refine ∧ᵢ (∧ₑ₁ h) ((∧ₑ₂ h) x)}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∧ᵢ (∧ₑ₁ (h (el t))) h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            have H1: π (p (ε (λ x, ¬ (p x))))\n                {refine ∧ₑ₂ (h (ε (λ x, ¬ (p x))))};\n            refine ⊥ₑ (H0 H1)}}\nend;\n\nopaque symbol ∀∧_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∧ a) = (`∀ x,p x ∧ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∧ a) (`∀ x, p x ∧ a) _ _\n        {assume h0 x;\n        rewrite ∧_com;\n        refine (=⇒ ((∀∧_dist_r t a p)) (=⇒ (∧_com (∀ p) a) h0)) x\n        }\n        {assume h0;\n        rewrite ∧_com;\n        have H0: π (`∀ x, a ∧ p x)\n            {assume x;\n            rewrite ∧_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∧_dist_r t a p)) H0\n        };\nend;\n\nopaque symbol ∀∨_dist_r t a (p : τ(t ⤳ o)): π ((a ∨ ∀ p) = (`∀ x, a ∨ p x))≔\nbegin\n    assume t a p;\n    refine propExt (a ∨ ∀ p) (∀(λ x, a ∨ p x)) _ _\n        {assume h x;\n        refine ∨ₑ h _ _\n            {assume h0;\n            refine ∨ᵢ₁ h0}\n            {assume h0;\n            refine ∨ᵢ₂ (h0 x)}}\n        {assume h;\n        refine ∨ₑ (em (∀ p)) _ _\n            {assume h1;\n            refine ∨ᵢ₂ h1}\n            {assume h1;\n            have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                {refine =⇒ (∀_skolem t p) h1};\n            refine ∨ₑ (h (ε (λ x, ¬ (p x)))) _ _\n                {assume h0;\n                refine ∨ᵢ₁ h0}\n                {assume h0;\n                refine ⊥ₑ (H0 h0)}}}\nend;\n\nopaque symbol ∀∨_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∨ a) = (`∀ x,p x ∨ a))≔\nbegin\n    assume t a p;\n    refine propExt (∀ p ∨ a) (`∀ x,p x ∨ a) _ _\n        {assume h0 x;\n        rewrite ∨_com;\n        refine (=⇒ ((∀∨_dist_r t a p)) (=⇒ (∨_com (∀ p) a) h0)) x}\n        {assume h0;\n        rewrite ∨_com;\n        have H0: π (`∀ x, a ∨ p x)\n            {assume x;\n            rewrite ∨_com;\n            refine h0 x};\n        refine =⇒ (eq_sym (∀∨_dist_r t a p)) H0};\nend;\n\nopaque symbol ∀_ext [t: Set] p q : π(`∀ (x : τ t), p x = q x) → π ((`∀ (x: τ t), p x) = (`∀ (x: τ t), q x))≔\nbegin\n    assume t p q h;\n    refine propExt (`∀ (x: τ t), p x) (`∀ (x: τ t), q x) _ _\n        {assume h1 x;\n        refine =⇒ (h x) (h1 x)}\n        {assume h1 x;\n        refine =⇒ (eq_sym (h x)) (h1 x)}\nend;\n\n\n/******************************************************************************\n*  Definition of Leo-III clausification tactic        \n******************************************************************************/\n\nsymbol normAsso ≔ #repeat ((#rewrite \"\" \"\" ∧_assoc) #orelse (#rewrite \"\" \"\" ∨_assoc));\n\nsymbol normAsso_∨ ≔ #repeat (#rewrite \"\" \"\" ∨_assoc);\n\nsymbol normAsso_∧ ≔ #repeat (#rewrite \"\" \"\" ∧_assoc);\n\nsymbol allCNFids_list ≔ ((#rewrite \"\" \"\" deMorgan_∧) ⸬ (#rewrite \"\" \"\" deMorgan_∨) ⸬ (#rewrite \"\" \"\" ⇒=∨) ⸬ (#rewrite \"\" \"\" ¬⇒=∧¬) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite \"\" \"\" ∧∨_dist_r) normAsso) ⸬ (#rewrite \"\" \"\" ¬¬ₑ_eq) ⸬ (#rewrite \"\" \"\" ∨_assoc) ⸬ (#rewrite \"\" \"\" ∧_assoc) ⸬ □);\n\nsymbol boolIds ≔ (applyAny allCNFids_list);\n\nsymbol tryVars: \uD835\uDD43 string → Tactic; \nrule tryVars ($v0 ⸬ ($v1 ⸬ $vs)) ↪ (#assume $v0) #orelse (tryVars ($v1 ⸬ $vs))\nwith tryVars ($v0 ⸬ □) ↪ (#assume $v0);\n\nsymbol move_∀_out (varList: \uD835\uDD43 string) ≔ #repeat (((#rewrite \"\" \"\" ∀∧_dist_r) #orelse (#rewrite  \"\" \"\" ∀∧_dist_l) #orelse (#rewrite  \"\" \"\" ∀∨_dist_r) #orelse (#rewrite \"\" \"\" ∀∨_dist_l)) #orelse (#and (#and (#refine \"∀_ext _ _ _\") (#simplify))) (tryVars varList));\n\nsymbol move_¬∃_out (varList: \uD835\uDD43 string) ≔ (#and (#rewrite \"\" \"\" ¬∃=∀¬) (move_∀_out varList));\n\nsymbol generalizeQuant (varList: \uD835\uDD43 string) ≔ (move_∀_out varList) #orelse (move_¬∃_out varList);\n\nsymbol skolemProzess_∃ sk_def : Tactic ≔ #and (#and (#rewrite \"\" \"\" ∃_skolem) sk_def) #simplify_beta;\n\nsymbol skolemProzess_∀ sk_def : Tactic ≔ #and (#and (#rewrite \"\" \"\" ∀_skolem) sk_def) #simplify_beta;\n\nsymbol skolemProzess sk_def : Tactic ≔ (skolemProzess_∀ sk_def) #orelse (skolemProzess_∃ sk_def);\n\n\nsymbol stepwise_skolem0: \uD835\uDD43 tactic → Tactic;\nrule stepwise_skolem0 ($sk1 ⸬ ($sk2 ⸬ $sk3)) ↪ #repeat ((#and (skolemProzess $sk1) (stepwise_skolem0 ($sk2 ⸬ $sk3))) #orelse boolIds)\nwith stepwise_skolem0 ($sk1 ⸬ □) ↪ #and (#repeat ((skolemProzess $sk1) #orelse boolIds)) #reflexivity;\n\nsymbol stepwise_skolem: (Tactic → Tactic) → \uD835\uDD43 tactic → Tactic;\nrule stepwise_skolem $t ($sk1 ⸬ ($sk2 ⸬ $sk3)) ↪ #repeat ((#and ($t $sk1) (stepwise_skolem $t ($sk2 ⸬ $sk3))) #orelse boolIds)\nwith stepwise_skolem $t ($sk1 ⸬ □) ↪ #and (#repeat (($t $sk1) #orelse boolIds)) #reflexivity;\n\nsymbol handleQuants (varList: \uD835\uDD43 string) (allSkolemRW : \uD835\uDD43 tactic) ≔ ((stepwise_skolem skolemProzess_∀ allSkolemRW) #orelse (move_∀_out varList)) #orelse ((move_¬∃_out varList) #orelse (stepwise_skolem skolemProzess_∃ allSkolemRW));\n\nsymbol cnfTac : \uD835\uDD43 string → \uD835\uDD43 tactic → Tactic;\nrule cnfTac □ □ ↪ #and (#repeat boolIds) #reflexivity\nwith cnfTac ($v0 ⸬ $v) □ ↪  #repeat ((generalizeQuant ($v0 ⸬ $v)) #orelse boolIds)\nwith cnfTac □ ($s0 ⸬ $s) ↪  stepwise_skolem skolemProzess ($s0 ⸬ $s)\nwith cnfTac ($v0 ⸬ $v) ($s0 ⸬ $s) ↪ #repeat ((handleQuants ($v0 ⸬ $v) ($s0 ⸬ $s)) #orelse boolIds);"
}
